// Extract and format horror content
const items = $input.all();
const horrorContent = [];
const crypto = require('crypto');

for (const item of items) {
  // Generate content hash for idempotency
  const contentHash = crypto
    .createHash('md5')
    .update(item.json.title + item.json.link)
    .digest('hex');

  const content = {
    idempotencyKey: `horror-${contentHash}`,
    title: item.json.title || 'Untitled Horror Content',
    link: item.json.link || item.json.guid || '',
    description: item.json.contentSnippet || item.json.description || '',
    pubDate: item.json.pubDate || new Date().toISOString(),
    categories: item.json.categories || ['horror'],
    horrorTags: generateHorrorTags(item.json.title),
    engagementScore: calculateEngagementScore(item.json),
    contentHash: contentHash
  };
  horrorContent.push(content);
}

return horrorContent.map(item => ({ json: item }));

function generateHorrorTags(title) {
  const horrorKeywords = [
    'horror', 'scary', 'terror', 'nightmare', 'creepy',
    'paranormal', 'supernatural', 'slasher', 'thriller',
    'ghost', 'vampire', 'zombie', 'monster', 'dark'
  ];

  const tags = ['horror'];
  const titleLower = title.toLowerCase();

  for (const keyword of horrorKeywords) {
    if (titleLower.includes(keyword) && !tags.includes(keyword)) {
      tags.push(keyword);
    }
  }

  return tags.slice(0, 5);
}

function calculateEngagementScore(item) {
  let score = 50;

  const highEngagementKeywords = ['exclusive', 'trailer', 'preview', 'new', 'breaking'];
  const title = (item.title || '').toLowerCase();

  for (const keyword of highEngagementKeywords) {
    if (title.includes(keyword)) {
      score += 10;
    }
  }

  return Math.min(score, 100);
}

// Check for duplicate content using idempotency key
const content = $input.first().json;
const idempotencyKey = content.idempotencyKey;

// In production, this would check a database or cache
// For now, we'll use a simple in-memory check via static data
const processedKeys = $static.processedKeys || new Set();

if (processedKeys.has(idempotencyKey)) {
  // Content already processed, skip
  return [{ json: { skip: true, reason: 'duplicate', idempotencyKey } }];
}

// Mark as processed
processedKeys.add(idempotencyKey);
$static.processedKeys = processedKeys;

// Return original content for processing
return [{ json: content }];

// Parse AI response and prepare YouTube upload data
const aiResponse = $input.first().json;
const originalContent = $input.first().json;
let parsedContent;

try {
  parsedContent = typeof aiResponse.message === 'string' 
    ? JSON.parse(aiResponse.message) 
    : aiResponse.message;
} catch (error) {
  // Fallback if JSON parsing fails
  parsedContent = {
    title: 'Horror Content - ' + new Date().toLocaleDateString(),
    description: aiResponse.message || 'Daily horror content update',
    tags: ['horror', 'scary', 'terror'],
    categoryId: 1
  };
}

const horrorData = {
  idempotencyKey: originalContent.idempotencyKey || 'unknown',
  snippet: {
    title: parsedContent.title || 'Untitled Horror Content',
    description: parsedContent.description || 'Daily horror content',
    categoryId: parsedContent.categoryId || 1,
    tags: parsedContent.tags || ['horror', 'scary', 'terror'],
    defaultLanguage: 'en',
    defaultAudioLanguage: 'en'
  },
  status: {
    privacyStatus: 'public',
    selfDeclaredMadeForKids: false
  },
  contentDetails: {
    caption: 'true'
  },
  metadata: {
    uploadDate: new Date().toISOString(),
    horrorGenre: true,
    contentRating: 'mature',
    originalLink: originalContent.link,
    engagementScore: originalContent.engagementScore
  }
};

return { json: horrorData };

// Format tweet for horror content promotion
const horrorContent = $input.first().json;
const tweet = {
  idempotencyKey: horrorContent.idempotencyKey + '-twitter',
  text: `🎃 ${horrorContent.title}\n\n${horrorContent.description.substring(0, 100)}...\n\n🔗 ${horrorContent.link}\n\n#Horror #Scary #Terror #HorrorCommunity`,
  media: horrorContent.imageUrl || null
};

return { json: tweet };

// Log successful upload and track analytics
const uploadResult = $input.first().json;

const logEntry = {
  timestamp: new Date().toISOString(),
  videoId: uploadResult.id || 'unknown',
  status: 'success',
  platform: 'youtube',
  contentType: 'horror',
  scheduledPost: true,
  engagement: {
    views: 0,
    likes: 0,
    comments: 0
  },
  idempotencyKey: uploadResult.idempotencyKey || 'unknown'
};

console.log('✅ Horror content uploaded successfully:', logEntry);

return { json: logEntry };

// Extract error details and format for notification
const error = $input.first().json;

const errorDetails = {
  timestamp: new Date().toISOString(),
  workflowName: 'Daily Horror YouTube Content Poster',
  executionId: error.executionId || 'unknown',
  node: error.node || 'unknown',
  errorMessage: error.error || error.message || 'Unknown error',
  errorStack: error.stack || '',
  workflowData: {
    mode: error.mode || 'unknown',
    retryCount: error.retryCount || 0
  }
};

return { json: errorDetails };

